using System;
using System.IO;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Media;
using System.Windows.Threading;
namespace DuoPet {
public class KeyboardTests {
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}
 public static InputState Preview(int code){var k=KeyboardLayout.Find(code);var s=new InputState{Time=.07,HitStarted=0,LastPhysical=code,BodyX=Math.Max(340,Math.Min(730,k.Center.X-80))};s.Physical[code]=true;s.KeyOrder[code]=1;return s;}
 public static void Unit(string path){Check(KeyboardLayout.All.Count==74,"Expected 74 caps, got "+KeyboardLayout.All.Count);var used=new HashSet<int>();foreach(var k in KeyboardLayout.All){Check(used.Add(k.Code),"duplicate physical scan code");Check(!String.IsNullOrWhiteSpace(k.Label),"blank cap");Check(k.Bounds.Left>=299&&k.Bounds.Right<=900&&k.Bounds.Top>=243&&k.Bounds.Bottom<=412,"cap outside keyboard");Check(Scene.KeyboardBounds(k.Bounds).Contains(Scene.StrikePoint(k)),"strike outside target cap");foreach(var other in KeyboardLayout.All)if(other!=k)Check(!k.Bounds.IntersectsWith(other.Bounds),"overlapping caps: "+k.Label+" and "+other.Label);
  var s=new InputState();using(var e=new InputEngine(s)){e.FeedPhysical(k.Vk,k.Code,true);Check(s.ActiveTarget==k,"wrong target "+k.Code);foreach(var other in KeyboardLayout.All)Check(s.Active(other.Code)==(other==k),"wrong key highlight");e.FeedPhysical(k.Vk,k.Code,false);Check(s.Active(k.Code),"short tap disappeared");s.Time+=1;Check(s.ActiveTarget==null,"stuck physical key");}}
 Check(KeyboardLayout.Normalize(13,0x1C,0)==0x1C&&KeyboardLayout.Normalize(13,0x1C,1)==0x11C,"Enter identity");Check(KeyboardLayout.Normalize(0x24,0x47,0)==0x47&&KeyboardLayout.Normalize(0x24,0x47,1)==0x147,"NumLock-off vs Home identity");
 var chord=new InputState();using(var e=new InputEngine(chord)){e.FeedPhysical(0xA2,0x1D,true);e.FeedPhysical(65,0x1E,true);Check(chord.Active(0x1D)&&chord.Active(0x1E)&&chord.ActiveTarget.Code==0x1E,"chord should highlight all, aim latest");e.FeedPhysical(65,0x1E,false);chord.Time+=1;Check(chord.ActiveTarget.Code==0x1D,"remaining held chord key");}
 foreach(int code in new[]{0x147,0x153,0x148,0x14B,0x150,0x14D,0x47,0x11C,0x137}){Check(KeyboardLayout.Find(code)==null,"removed key remains visible");var hidden=new InputState();using(var engine=new InputEngine(hidden)){engine.FeedPhysical(13,code,true);Check(hidden.ActiveTarget==null,"removed key incorrectly targets visible cap");}}
 var fixedState=new InputState();using(var engine=new InputEngine(fixedState)){engine.FeedPhysical(65,0x1E,true);engine.Tick();Check(fixedState.BodyX==540,"Yier must remain fixed");}

 Check(Scene.KeyboardPoint(KeyboardLayout.Find(0x39).Center).Y<Scene.KeyboardPoint(KeyboardLayout.Find(0x01).Center).Y,"Space side must face Yier");
 foreach(var key in KeyboardLayout.All){var original=key.Center;var twice=Scene.KeyboardPoint(Scene.KeyboardPoint(original));Check((twice-original).Length<.001,"rotation must preserve key identity");}
 var bounds=System.Windows.Forms.Screen.PrimaryScreen.Bounds;int cx=bounds.Left+bounds.Width/2,cy=bounds.Top+bounds.Height/2;
 foreach(int dx in new[]{-30,30}){var ms=new InputState();using(var engine=new InputEngine(ms)){engine.FeedMouse(0x200,cx+dx,cy);engine.Tick();Check(ms.MouseX*dx<0,"horizontal mouse direction not inverted");}}
 foreach(int dy in new[]{-30,30}){var ms=new InputState();using(var engine=new InputEngine(ms)){engine.FeedMouse(0x200,cx,cy+dy);engine.Tick();Check(ms.MouseY*dy<0,"vertical mouse direction not inverted");}}
 File.WriteAllText(path,"PASS: 74 unique labeled non-overlapping caps, all scan mappings individually highlight only their cap, strike centers within cap, short tap + release, removed navigation/numpad keys do not aim at visible caps, fixed Yier body, four mouse directions inverted, 180-degree rotation with Space facing Yier, multi-key chord highlights with latest target.");}
 public static void Integration(string folder){Directory.CreateDirectory(folder);var app=new Application();var s=new InputState();var eng=new InputEngine(s);var w=new Window{Title="桌宠 · 物理键帽映射测试",Width=440,Height=170,WindowStartupLocation=WindowStartupLocation.CenterScreen,Topmost=true,Background=Brushes.White};w.Content=new System.Windows.Controls.TextBlock{Text="正在核对实际按键与键帽位置…",FontSize=17,Margin=new Thickness(24)};
 int[] codes={0x1E,0x24,0x02,0x27,0x35,0x40,0x2A,0x36,0x1D,0x11D,0x1C,0x10,0x0F,0x0E,0x58,0x2C,0x39};int index=0,phase=0;bool pass=false;IntPtr hwnd=IntPtr.Zero;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(180)};
 Action done=()=>{timer.Stop();Native.Scan(0x58,false);Native.Scan(0x1E,false);if(index<codes.Length)Native.Scan(codes[index],false);eng.Dispose();w.Close();};
 timer.Tick+=(a,b)=>{try{eng.Tick();Check(Native.GetForegroundWindow()==hwnd,"Test focus changed, stopping injection");int code=codes[Math.Min(index,codes.Length-1)];switch(phase){case 0:Native.Scan(code,true);phase=1;break;case 1:Check(s.Physical[code],"actual hook did not identify code "+code);Check(s.ActiveTarget!=null&&s.ActiveTarget.Code==code,"actual paddle target wrong "+code);if(code==0x1C||code==0x11C||code==0x47||code==0x1E){s.BodyX=Math.Max(340,Math.Min(730,s.ActiveTarget.Center.X-80));Scene.Render(Path.Combine(folder,"scan-"+code+".png"),s);}Native.Scan(code,false);phase=2;break;case 2:Check(!s.Active(code),"actual release stuck "+code);index++;phase=0;if(index==codes.Length){phase=3;}break;case 3:Native.Scan(0x58,true);phase=4;break;case 4:Native.Scan(0x1E,true);phase=5;break;case 5:Check(s.ActiveTarget.Code==0x1E,"latest before pause");eng.Pause(true);eng.Pause(false);Check(s.Physical[0x58]&&s.Physical[0x1E]&&s.ActiveTarget.Code==0x1E,"pause lost latest target");Native.Scan(0x1E,false);phase=6;break;case 6:Check(s.ActiveTarget.Code==0x58,"release should return to held F12");Native.Scan(0x58,false);phase=7;break;case 7:Check(s.ActiveTarget==null,"release after pause stuck");{pass=true;File.WriteAllText(Path.Combine(folder,"scan-test.txt"),"PASS: 17 actual Windows SendInput scan-code pairs. Letters, number row, punctuation, F6/F12, left/right Shift/Ctrl, main Enter, Q, Tab, Backspace, Z, Space all hit their own physical caps and release. F12 + A pause/resume preserves latest A target, releasing A returns to held F12, final release clears.");done();}break;}}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"scan-error.txt"),ex.ToString());done();}};
 w.Loaded+=(a,b)=>{try{hwnd=new WindowInteropHelper(w).Handle;w.Activate();w.Focus();eng.Start();timer.Start();}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"scan-error.txt"),ex.ToString());done();}};app.Run(w);Environment.ExitCode=pass?0:1;}
}
}
